const assert = require("node:assert/strict");
const { mkdtemp, rm } = require("node:fs/promises");
const { tmpdir } = require("node:os");
const { join } = require("node:path");
const test = require("node:test");

const { createPendingCaptureQueue } = require("../chrome-extension/native/pending-captures.cjs");

test("persists screenshot-bearing captures until Pi acknowledges recovery", async (t) => {
  const directory = await mkdtemp(join(tmpdir(), "pi-annotate-pending-test-"));
  const filePath = join(directory, "pending-captures.json");
  t.after(() => rm(directory, { recursive: true, force: true }));

  const queue = createPendingCaptureQueue({ filePath });
  const capture = queue.enqueue({
    type: "ANNOTATIONS_COMPLETE",
    requestId: 17,
    result: {
      success: true,
      url: "https://example.test",
      elements: [],
      screenshot: "data:image/png;base64,c2NyZWVuc2hvdA==",
    },
  });

  const reopenedQueue = createPendingCaptureQueue({ filePath });
  assert.deepEqual(reopenedQueue.read(), [{
    id: capture.id,
    message: {
      type: "ANNOTATIONS_COMPLETE",
      requestId: 17,
      result: {
        success: true,
        url: "https://example.test",
        elements: [],
        screenshot: "data:image/png;base64,c2NyZWVuc2hvdA==",
      },
    },
  }]);

  reopenedQueue.acknowledge([capture.id]);
  assert.deepEqual(reopenedQueue.read(), []);
});

import test from 'node:test';
import assert from 'node:assert/strict';

import * as remoteNamespace from '../remote.ts';

const {
  makeLocalSocketPath,
  parseAnnotateCommandArgs,
  parseWslBridgeEnv,
  planRemotePageAccess,
} = remoteNamespace.default ?? remoteNamespace;

test('parseAnnotateCommandArgs preserves same-machine URL forms', () => {
  assert.deepEqual(parseAnnotateCommandArgs(''), { mode: 'same-machine' });
  assert.deepEqual(parseAnnotateCommandArgs('https://example.com/a b'), { mode: 'same-machine', url: 'https://example.com/a b' });
  assert.deepEqual(parseAnnotateCommandArgs('http://localhost:3000'), { mode: 'same-machine', url: 'http://localhost:3000' });
});

test('parseAnnotateCommandArgs treats first non-URL token as Browser Host', () => {
  assert.deepEqual(parseAnnotateCommandArgs('laptop'), { mode: 'browser-host', browserHost: 'laptop' });
  assert.deepEqual(parseAnnotateCommandArgs('laptop http://localhost:3000'), { mode: 'browser-host', browserHost: 'laptop', url: 'http://localhost:3000' });
});

test('planRemotePageAccess rewrites supported loopback URLs to Browser Host loopback port', () => {
  assert.deepEqual(planRemotePageAccess('http://localhost:3000/path?q=1#hash', 49152), {
    url: 'http://127.0.0.1:49152/path?q=1#hash',
    tunnel: { browserPort: 49152, targetHost: '127.0.0.1', targetPort: 3000 },
  });
  assert.deepEqual(planRemotePageAccess('https://127.0.0.1/settings', 49152), {
    url: 'https://127.0.0.1:49152/settings',
    tunnel: { browserPort: 49152, targetHost: '127.0.0.1', targetPort: 443 },
  });
  assert.deepEqual(planRemotePageAccess('http://[::1]:3000', 49152), { url: 'http://[::1]:3000' });
  assert.deepEqual(planRemotePageAccess('https://example.com', 49152), { url: 'https://example.com' });
});

test('makeLocalSocketPath stays short for long SSH aliases', () => {
  const socketPath = makeLocalSocketPath('a'.repeat(120));
  assert.equal(socketPath.startsWith('/tmp/pa-'), true);
  assert.equal(socketPath.endsWith('.sock'), true);
  assert.equal(Buffer.byteLength(socketPath), socketPath.length);
  assert.ok(socketPath.length < 104);
});


test('parseWslBridgeEnv requires explicit bridge and token', () => {
  assert.equal(parseWslBridgeEnv({}), null);
  assert.deepEqual(parseWslBridgeEnv({
    PI_ANNOTATE_WSL_BRIDGE: '127.0.0.1:43173',
    PI_ANNOTATE_WSL_TOKEN: 'secret',
  }), { host: '127.0.0.1', port: 43173, token: 'secret' });
  assert.throws(() => parseWslBridgeEnv({ PI_ANNOTATE_WSL_BRIDGE: '127.0.0.1:43173' }), /Set both PI_ANNOTATE_WSL_BRIDGE/);
  assert.throws(() => parseWslBridgeEnv({ PI_ANNOTATE_WSL_BRIDGE: '127.0.0.1:notaport', PI_ANNOTATE_WSL_TOKEN: 'secret' }), /host:port/);
  assert.throws(() => parseWslBridgeEnv({ PI_ANNOTATE_WSL_BRIDGE: '0.0.0.0:43173', PI_ANNOTATE_WSL_TOKEN: 'secret' }), /loopback host:port/);
});

const assert = require("node:assert/strict");
const { spawn } = require("node:child_process");
const { readFileSync } = require("node:fs");
const { mkdtemp, readFile, rm, stat, writeFile } = require("node:fs/promises");
const net = require("node:net");
const { tmpdir } = require("node:os");
const { join } = require("node:path");
const test = require("node:test");

const hostPath = join(__dirname, "../chrome-extension/native/host.cjs");
const indexPath = join(__dirname, "../index.ts");

function readMegabyteConstant(filePath, name) {
  const source = readFileSync(filePath, "utf8");
  const match = source.match(new RegExp(`const ${name} = (\\d+) \\* 1024 \\* 1024`));
  assert.ok(match, `Could not find ${name} in ${filePath}`);
  return Number(match[1]) * 1024 * 1024;
}

function waitFor(check, timeoutMs = 3_000) {
  const deadline = Date.now() + timeoutMs;
  return new Promise((resolve, reject) => {
    const attempt = async () => {
      try {
        const value = await check();
        if (value) return resolve(value);
      } catch {
        // The host has not created this resource yet.
      }
      if (Date.now() >= deadline) return reject(new Error("Timed out waiting for host"));
      setTimeout(attempt, 20);
    };
    attempt();
  });
}

function writeNativeMessage(stream, message) {
  const json = Buffer.from(JSON.stringify(message));
  const length = Buffer.alloc(4);
  length.writeUInt32LE(json.length);
  stream.write(Buffer.concat([length, json]));
}

function readSocketMessages(socket, count) {
  return new Promise((resolve, reject) => {
    let buffer = "";
    const messages = [];
    const timeout = setTimeout(() => reject(new Error("Timed out waiting for Pi socket messages")), 3_000);
    const onData = (chunk) => {
      buffer += chunk;
      let newline;
      while ((newline = buffer.indexOf("\n")) >= 0) {
        const line = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);
        if (!line.trim()) continue;
        messages.push(JSON.parse(line));
        if (messages.length === count) {
          clearTimeout(timeout);
          socket.removeListener("data", onData);
          resolve(messages);
          return;
        }
      }
    };
    socket.on("data", onData);
    socket.once("error", (error) => {
      clearTimeout(timeout);
      reject(error);
    });
  });
}

test("native host recovers pending capture only after Pi requests it and removes it after ACK", async (t) => {
  const directory = await mkdtemp(join(tmpdir(), "pi-annotate-host-test-"));
  const paths = {
    socket: join(directory, "host.sock"),
    token: [REDACTED], "token"),
    pid: join(directory, "host.pid"),
    lock: join(directory, "host.lock"),
    log: join(directory, "host.log"),
    queue: join(directory, "queue.json"),
  };
  const host = spawn(process.execPath, [hostPath], {
    env: {
      ...process.env,
      PI_ANNOTATE_SOCKET: paths.socket,
      PI_ANNOTATE_TOKEN: paths.token,
      PI_ANNOTATE_PID: paths.pid,
      PI_ANNOTATE_LOCK: paths.lock,
      PI_ANNOTATE_LOG: paths.log,
      PI_ANNOTATE_PENDING_CAPTURES: paths.queue,
    },
    stdio: ["pipe", "ignore", "pipe"],
  });
  let stderr = "";
  host.stderr.on("data", (chunk) => { stderr += chunk; });
  t.after(async () => {
    host.kill("SIGTERM");
    await new Promise((resolve) => host.once("exit", resolve));
    await rm(directory, { recursive: true, force: true });
  });

  await waitFor(async () => {
    await stat(paths.socket);
    return true;
  });
  writeNativeMessage(host.stdin, {
    type: "ANNOTATIONS_COMPLETE",
    result: {
      success: true,
      url: "https://example.test",
      elements: [],
      screenshot: "data:image/png;base64,c2NyZWVuc2hvdA==",
    },
  });
  await waitFor(async () => JSON.parse(await readFile(paths.queue, "utf8")).length === 1);

  const token = (await readFile(paths.token, "utf8")).trim();
  const pi = net.createConnection(paths.socket);
  await new Promise((resolve, reject) => {
    pi.once("connect", resolve);
    pi.once("error", reject);
  });
  pi.write(`${JSON.stringify({ type: "AUTH", token })}\n`);
  pi.write(`${JSON.stringify({ type: "RECOVER_PENDING_ANNOTATIONS" })}\n`);
  const [recovered] = await readSocketMessages(pi, 1);
  assert.equal(recovered.type, "PENDING_ANNOTATIONS");
  assert.equal(recovered.captures.length, 1);
  assert.equal(recovered.captures[0].message.result.screenshot, "data:image/png;base64,c2NyZWVuc2hvdA==");

  pi.write(`${JSON.stringify({ type: "ACK_PENDING_ANNOTATIONS", captureIds: [recovered.captures[0].id] })}\n`);
  await waitFor(async () => JSON.parse(await readFile(paths.queue, "utf8")).length === 0);
  pi.destroy();
  assert.equal(stderr, "");
});

test("native host recovers multiple queued captures in individually bounded messages", async (t) => {
  const directory = await mkdtemp(join(tmpdir(), "pi-annotate-host-test-"));
  const paths = {
    socket: join(directory, "host.sock"),
    token: [REDACTED], "token"),
    pid: join(directory, "host.pid"),
    lock: join(directory, "host.lock"),
    log: join(directory, "host.log"),
    queue: join(directory, "queue.json"),
  };
  const captures = Array.from({ length: 3 }, (_, index) => ({
    id: `capture-${index}`,
    message: {
      type: "ANNOTATIONS_COMPLETE",
      requestId: index + 1,
      result: {
        success: true,
        url: `https://example.test/${index}`,
        elements: [],
        screenshot: `data:image/png;base64,${"x".repeat(700)}`,
      },
    },
  }));
  await writeFile(paths.queue, JSON.stringify(captures));

  const socketMessageLimit = 2 * 1024;
  const aggregateMessage = JSON.stringify({ type: "PENDING_ANNOTATIONS", captures }) + "\n";
  assert.ok(Buffer.byteLength(aggregateMessage) > socketMessageLimit);
  for (const capture of captures) {
    const individualMessage = JSON.stringify({ type: "PENDING_ANNOTATIONS", captures: [capture] }) + "\n";
    assert.ok(Buffer.byteLength(individualMessage) < socketMessageLimit);
  }

  const host = spawn(process.execPath, [hostPath], {
    env: {
      ...process.env,
      PI_ANNOTATE_SOCKET: paths.socket,
      PI_ANNOTATE_TOKEN: paths.token,
      PI_ANNOTATE_PID: paths.pid,
      PI_ANNOTATE_LOCK: paths.lock,
      PI_ANNOTATE_LOG: paths.log,
      PI_ANNOTATE_PENDING_CAPTURES: paths.queue,
    },
    stdio: ["pipe", "ignore", "pipe"],
  });
  let stderr = "";
  host.stderr.on("data", (chunk) => { stderr += chunk; });
  t.after(async () => {
    host.kill("SIGTERM");
    await new Promise((resolve) => host.once("exit", resolve));
    await rm(directory, { recursive: true, force: true });
  });

  await waitFor(async () => {
    await stat(paths.socket);
    return true;
  });
  const token = (await readFile(paths.token, "utf8")).trim();
  const pi = net.createConnection(paths.socket);
  await new Promise((resolve, reject) => {
    pi.once("connect", resolve);
    pi.once("error", reject);
  });
  pi.write(`${JSON.stringify({ type: "AUTH", token })}\n`);
  pi.write(`${JSON.stringify({ type: "RECOVER_PENDING_ANNOTATIONS" })}\n`);

  const recovered = await readSocketMessages(pi, captures.length);
  assert.deepEqual(recovered.map((message) => message.type), captures.map(() => "PENDING_ANNOTATIONS"));
  assert.deepEqual(recovered.map((message) => message.captures.map((capture) => capture.id)), captures.map((capture) => [capture.id]));
  assert.deepEqual(recovered.map((message) => message.captures[0].message.result.screenshot), captures.map((capture) => capture.message.result.screenshot));
  assert.ok(recovered.every((message) => Buffer.byteLength(JSON.stringify(message) + "\n") < socketMessageLimit));
  assert.equal(JSON.parse(await readFile(paths.queue, "utf8")).length, captures.length);

  pi.write(`${JSON.stringify({ type: "ACK_PENDING_ANNOTATIONS", captureIds: captures.map((capture) => capture.id) })}\n`);
  await waitFor(async () => JSON.parse(await readFile(paths.queue, "utf8")).length === 0);
  pi.destroy();
  assert.equal(stderr, "");
});

test("socket receiver leaves room for a max-size native capture recovery envelope", () => {
  const maxNativeMessageBytes = readMegabyteConstant(hostPath, "MAX_NATIVE_MESSAGE_BYTES");
  const maxSocketBuffer = readMegabyteConstant(indexPath, "MAX_SOCKET_BUFFER");
  const nativeMessage = {
    type: "ANNOTATIONS_COMPLETE",
    result: {
      success: true,
      url: "https://example.test",
      elements: [],
      screenshot: "data:image/png;base64,",
    },
  };
  const nativeMessageWithoutPayload = JSON.stringify(nativeMessage);
  nativeMessage.result.screenshot += "x".repeat(maxNativeMessageBytes - Buffer.byteLength(nativeMessageWithoutPayload));

  const nativeMessageBytes = Buffer.byteLength(JSON.stringify(nativeMessage));
  const recoveryFrame = JSON.stringify({
    type: "PENDING_ANNOTATIONS",
    captures: [{
      id: "00000000-0000-0000-0000-000000000000",
      message: nativeMessage,
    }],
  }) + "\n";
  const recoveryFrameBytes = Buffer.byteLength(recoveryFrame);

  assert.equal(nativeMessageBytes, maxNativeMessageBytes);
  assert.ok(recoveryFrameBytes > nativeMessageBytes);
  assert.ok(recoveryFrameBytes <= maxSocketBuffer, `${recoveryFrameBytes} > ${maxSocketBuffer}`);
});

import { execFile, spawn, type ChildProcessByStdio } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import type { Readable } from "node:stream";

const REMOTE_SOCKET_PATH = "/tmp/pi-annotate.sock";
const REMOTE_TOKEN_PATH = "/tmp/pi-annotate.token";
const SSH_READY_TIMEOUT_MS = 5000;
const SSH_TUNNEL_TIMEOUT_MS = 7000;

type RemotePageTunnel = {
  browserPort: number;
  targetHost: string;
  targetPort: number;
};

export type RemoteAnnotationBridge = {
  browserHost: string;
  socketPath: string;
  token: string;
  url?: string;
  cleanup: () => void;
};

export type ParsedAnnotateArgs =
  | { mode: "same-machine"; url?: string }
  | { mode: "browser-host"; browserHost: string; url?: string };

export type WslBridgeConfig = {
  host: string;
  port: number;
  token: string;
};

export class RemoteAnnotationError extends Error {
  code: string;

  constructor(code: string, message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "RemoteAnnotationError";
    this.code = code;
  }
}

export function parseAnnotateCommandArgs(args: string): ParsedAnnotateArgs {
  const trimmed = args.trim();
  if (!trimmed) return { mode: "same-machine" };

  const [first, ...rest] = trimmed.split(/\s+/);
  if (isUrlLike(first)) return { mode: "same-machine", url: trimmed };

  const url = rest.length > 0 ? rest.join(" ") : null;
  return url
    ? { mode: "browser-host", browserHost: first, url }
    : { mode: "browser-host", browserHost: first };
}

export function isUrlLike(value: string): boolean {
  return /^[a-z][a-z0-9+.-]*:\/\//i.test(value);
}

export function isRemoteLoopbackUrl(rawUrl: string | undefined): boolean {
  const hostname = getPageHostname(rawUrl);
  return !!hostname && isSupportedLoopbackHostname(hostname);
}

function isUnsupportedLoopbackUrl(rawUrl: string | undefined): boolean {
  const hostname = getPageHostname(rawUrl);
  return hostname === "::1";
}

function getPageHostname(rawUrl: string | undefined): string | null {
  if (!rawUrl) return null;
  try {
    const parsed = new URL(rawUrl);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;
    return parsed.hostname.toLowerCase().replace(/^\[/, "").replace(/\]$/, "");
  } catch {
    return null;
  }
}

function isSupportedLoopbackHostname(hostname: string): boolean {
  return hostname === "localhost" || /^127(?:\.\d{1,3}){3}$/.test(hostname);
}

function isWslBridgeLoopbackHost(hostname: string): boolean {
  return hostname === "localhost" || hostname === "::1" || /^127(?:\.\d{1,3}){3}$/.test(hostname);
}

export function planRemotePageAccess(rawUrl: string | undefined, browserPort: number): { url?: string; tunnel?: RemotePageTunnel } {
  if (!rawUrl) return {};
  if (!isRemoteLoopbackUrl(rawUrl)) return { url: rawUrl };

  const parsed = new URL(rawUrl);
  const targetPort = Number.parseInt(parsed.port || defaultPortForProtocol(parsed.protocol), 10);
  parsed.hostname = "127.0.0.1";
  parsed.port = String(browserPort);

  return {
    url: parsed.toString(),
    tunnel: {
      browserPort,
      targetHost: "127.0.0.1",
      targetPort,
    },
  };
}

function defaultPortForProtocol(protocol: string): string {
  return protocol === "https:" ? "443" : "80";
}

export function parseWslBridgeEnv(env: NodeJS.ProcessEnv = process.env): WslBridgeConfig | null {
  const target = env.PI_ANNOTATE_WSL_BRIDGE?.trim();
  const token = [REDACTED];
  if (!target && !token) return null;
  if (!target || !token) {
    throw new RemoteAnnotationError(
      "WSL_BRIDGE_CONFIG_INCOMPLETE",
      "Set both PI_ANNOTATE_WSL_BRIDGE and PI_ANNOTATE_WSL_TOKEN in WSL before using the Windows Browser Host bridge."
    );
  }

  try {
    const parsed = target.includes("://") ? new URL(target) : new URL(`tcp://${target}`);
    const host = parsed.hostname.toLowerCase().replace(/^\[/, "").replace(/\]$/, "");
    const port = Number.parseInt(parsed.port, 10);
    if (!host || !Number.isInteger(port) || port < 1 || port > 65535) throw new Error("invalid host or port");
    if (!isWslBridgeLoopbackHost(host)) throw new Error("bridge host must be loopback");
    return { host, port, token };
  } catch (err) {
    throw new RemoteAnnotationError(
      "WSL_BRIDGE_CONFIG_INVALID",
      "PI_ANNOTATE_WSL_BRIDGE must be a loopback host:port value such as 127.0.0.1:43173.",
      { cause: err }
    );
  }
}

function assertBrowserHost(browserHost: string) {
  if (!/^[A-Za-z0-9_.@:-]+$/.test(browserHost) || browserHost.startsWith("-")) {
    throw new RemoteAnnotationError(
      "BROWSER_HOST_INVALID",
      "Browser Host must be an SSH host alias, hostname, or user@host without spaces or shell metacharacters."
    );
  }
}

function classifySshFailure(detail: string): { code: string; message: string } | null {
  if (/Host key verification failed|REMOTE HOST IDENTIFICATION HAS CHANGED|No .* host key is known/i.test(detail)) {
    return {
      code: "SSH_HOST_KEY_FAILED",
      message: "SSH host-key verification failed. Run ssh to the Browser Host once from the Pi Session Host, then retry.",
    };
  }
  if (/Permission denied/i.test(detail)) {
    return {
      code: "SSH_AUTH_FAILED",
      message: "SSH authentication failed. Configure non-interactive SSH so BatchMode works from the Pi Session Host.",
    };
  }
  if (/Could not resolve hostname|Name or service not known|nodename nor servname provided/i.test(detail)) {
    return {
      code: "SSH_HOST_UNRESOLVED",
      message: "SSH could not resolve the Browser Host. Check the SSH alias from the Pi Session Host.",
    };
  }
  if (/Connection timed out|Connection refused|No route to host|Operation timed out/i.test(detail)) {
    return {
      code: "SSH_CONNECT_FAILED",
      message: "SSH could not connect to the Browser Host. Check that it is online and reachable.",
    };
  }
  return null;
}

function sshBaseArgs(browserHost: string): string[] {
  return ["-o", "BatchMode=yes", "-o", "ConnectTimeout=5", browserHost];
}

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

function remoteNodeEval(script: string): string {
  return `node -e ${shellQuote(script)}`;
}

function execFileText(file: string, args: string[], timeout = SSH_READY_TIMEOUT_MS): Promise<string> {
  return new Promise((resolve, reject) => {
    execFile(file, args, { timeout, maxBuffer: 1024 * 1024 }, (err, stdout, stderr) => {
      if (err) {
        reject(new Error(stderr.trim() || err.message, { cause: err }));
        return;
      }
      resolve(stdout);
    });
  });
}

async function readRemoteToken(browserHost: string): Promise<string> {
  try {
    const token = (await execFileText("ssh", [...sshBaseArgs(browserHost), "cat", REMOTE_TOKEN_PATH])).trim();
    if (!token) throw new Error("remote token file is empty");
    return token;
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err);
    const sshFailure = classifySshFailure(detail);
    if (sshFailure) throw new RemoteAnnotationError(sshFailure.code, `${sshFailure.message} (${detail})`, { cause: err });
    throw new RemoteAnnotationError(
      "BROWSER_HOST_NOT_READY",
      `Browser Host '${browserHost}' is not ready. Open Chrome or Chromium there, click the Pi Annotate extension icon, then retry. (${detail})`,
      { cause: err }
    );
  }
}

async function pickBrowserHostPort(browserHost: string): Promise<number> {
  const script = "const net=require('node:net');const s=net.createServer();s.listen(0,'127.0.0.1',()=>{console.log(s.address().port);s.close();});";
  const stdout = await execFileText("ssh", [...sshBaseArgs(browserHost), remoteNodeEval(script)]);
  const port = Number.parseInt(stdout.trim(), 10);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new RemoteAnnotationError("REMOTE_PORT_UNAVAILABLE", `Could not allocate a loopback port on Browser Host '${browserHost}'.`);
  }
  return port;
}

export function makeLocalSocketPath(_browserHost: string): string {
  const suffix = `${process.pid}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  return path.join("/tmp", `pa-${suffix}.sock`);
}

function unlinkIfExists(filePath: string) {
  try {
    fs.unlinkSync(filePath);
  } catch (err) {
    const code = err && typeof err === "object" && "code" in err ? err.code : "";
    if (code !== "ENOENT") throw err;
  }
}

function waitForLocalSocket(proc: ChildProcessByStdio<null, null, Readable>, socketPath: string): Promise<void> {
  return new Promise((resolve, reject) => {
    let settled = false;
    let stderr = "";
    const intervalId = setInterval(() => {
      if (fs.existsSync(socketPath)) finish(resolve);
    }, 50);
    const timeoutId = setTimeout(() => {
      finish(reject, new RemoteAnnotationError("SSH_TUNNEL_TIMEOUT", `Timed out waiting for SSH tunnel. ${stderr.trim()}`.trim()));
    }, SSH_TUNNEL_TIMEOUT_MS);

    function cleanup() {
      clearInterval(intervalId);
      clearTimeout(timeoutId);
      proc.off("error", onError);
      proc.off("exit", onExit);
      proc.stderr.off("data", onStderr);
    }

    function finish<T>(fn: (value: T) => void, value?: T) {
      if (settled) return;
      settled = true;
      cleanup();
      fn(value as T);
    }

    function onStderr(chunk: Buffer) {
      stderr += chunk.toString();
    }

    function onError(err: Error) {
      finish(reject, new RemoteAnnotationError("SSH_TUNNEL_FAILED", `Failed to start SSH tunnel: ${err.message}`, { cause: err }));
    }

    function onExit(code: number | null, signal: NodeJS.Signals | null) {
      finish(reject, new RemoteAnnotationError(
        "SSH_TUNNEL_FAILED",
        `SSH tunnel exited before it became ready (code=${code ?? "null"}, signal=${signal ?? "null"}). ${stderr.trim()}`.trim()
      ));
    }

    proc.stderr.on("data", onStderr);
    proc.once("error", onError);
    proc.once("exit", onExit);
  });
}

export async function createRemoteAnnotationBridge(options: { browserHost: string; url?: string }): Promise<RemoteAnnotationBridge> {
  const { browserHost, url } = options;
  assertBrowserHost(browserHost);
  if (isUnsupportedLoopbackUrl(url)) {
    throw new RemoteAnnotationError(
      "LOOPBACK_URL_UNSUPPORTED",
      "Remote annotation supports localhost and 127.0.0.1 loopback URLs. Use one of those instead of IPv6 loopback."
    );
  }

  const token = await readRemoteToken(browserHost);
  const browserPort = isRemoteLoopbackUrl(url) ? await pickBrowserHostPort(browserHost) : 0;
  const pageAccess = planRemotePageAccess(url, browserPort);
  const socketPath = makeLocalSocketPath(browserHost);
  unlinkIfExists(socketPath);

  const args = [
    ...sshBaseArgs(browserHost).slice(0, -1),
    "-o",
    "ExitOnForwardFailure=yes",
    "-o",
    "StreamLocalBindUnlink=yes",
    "-N",
    "-L",
    `${socketPath}:${REMOTE_SOCKET_PATH}`,
  ];

  if (pageAccess.tunnel) {
    args.push("-R", `127.0.0.1:${pageAccess.tunnel.browserPort}:${pageAccess.tunnel.targetHost}:${pageAccess.tunnel.targetPort}`);
  }

  args.push(browserHost);

  const proc = spawn("ssh", args, { stdio: ["ignore", "ignore", "pipe"] });
  try {
    await waitForLocalSocket(proc, socketPath);
  } catch (err) {
    proc.kill("SIGTERM");
    unlinkIfExists(socketPath);
    throw err;
  }

  let cleaned = false;
  const bridge = {
    browserHost,
    socketPath,
    token,
    cleanup() {
      if (cleaned) return;
      cleaned = true;
      proc.kill("SIGTERM");
      unlinkIfExists(socketPath);
    },
  };
  return pageAccess.url === undefined ? bridge : { ...bridge, url: pageAccess.url };
}

/** Element bounding rectangle in page coordinates */
export interface ElementRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Box model breakdown (content, padding, border, margin) */
export interface BoxModel {
  content: { width: number; height: number };
  padding: { top: number; right: number; bottom: number; left: number };
  border: { top: number; right: number; bottom: number; left: number };
  margin: { top: number; right: number; bottom: number; left: number };
}

/** Accessibility information for an element */
export interface AccessibilityInfo {
  /** ARIA role (explicit or implicit) */
  role: string | null;
  /** Computed accessible name */
  name: string | null;
  /** aria-describedby content */
  description: string | null;
  /** Whether element can receive focus */
  focusable: boolean;
  /** Whether element is disabled */
  disabled: boolean;
  /** aria-expanded state */
  expanded?: boolean;
  /** aria-pressed state */
  pressed?: boolean;
  /** Checked state (native or aria-checked) */
  checked?: boolean;
  /** Selected state (native or aria-selected) */
  selected?: boolean;
}

/** Parent element context for debugging layout issues */
export interface ParentContext {
  /** Parent tag name */
  tag: string;
  /** Parent ID if present */
  id?: string;
  /** Parent CSS classes */
  classes: string[];
  /** Layout-relevant computed styles */
  styles: Record<string, string>;
}

/** Information about a selected DOM element */
export interface ElementSelection {
  /** CSS selector that uniquely identifies this element */
  selector: string;
  /** HTML tag name (lowercase) */
  tag: string;
  /** Element ID if present */
  id: string | null;
  /** Array of CSS class names */
  classes: string[];
  /** Truncated text content */
  text: string;
  /** Bounding rectangle */
  rect: ElementRect;
  /** Selected HTML attributes */
  attributes: Record<string, string>;
  /** Per-element annotation comment */
  comment?: string;
  /** Box model breakdown (always captured) */
  boxModel?: BoxModel;
  /** Accessibility info (always captured) */
  accessibility?: AccessibilityInfo;
  /** Key CSS properties (always captured) */
  keyStyles?: Record<string, string>;
  /** Computed styles (debug mode only) */
  computedStyles?: Record<string, string>;
  /** Parent context (debug mode only) */
  parentContext?: ParentContext;
  /** CSS custom properties (debug mode only) */
  cssVariables?: Record<string, string>;
}

/** Screenshot cropped to a specific element */
export interface ElementScreenshot {
  /** 1-based index matching the element number */
  index: number;
  /** Base64 data URL of the cropped screenshot */
  dataUrl: string;
}

/** Viewport dimensions */
export interface Viewport {
  width: number;
  height: number;
}

/** Individual CSS property change */
export interface StylePropertyChange {
  property: string;
  from: string;
  to: string;
}

/** Inline style changes on a specific element */
export interface InlineStyleChange {
  selector: string;
  tag: string;
  added: Record<string, string>;
  changed: StylePropertyChange[];
  removed: string[];
}

/** CSS rule change in a stylesheet */
export interface RuleChange {
  ruleSelector: string;
  sheet: string;
  added: Record<string, string>;
  changed: StylePropertyChange[];
  removed: string[];
}

/** DOM mutation (text, attribute, structural) */
export interface DOMChange {
  type: "text" | "attribute" | "added" | "removed" | "structural";
  selector: string;
  detail: string;
}

/** Complete edit capture result */
export interface EditCapture {
  inlineStyles: InlineStyleChange[];
  rules: RuleChange[];
  dom: DOMChange[];
  beforeScreenshot?: string;
  afterScreenshot?: string;
  duration: number;
  changeCount: number;
  warnings?: string[];
}

/** Result returned from annotation session */
export interface AnnotationResult {
  /** Whether the annotation completed successfully */
  success: boolean;
  /** Selected elements with their metadata */
  elements?: ElementSelection[];
  /** Full page screenshot (when fullPage mode is enabled) */
  screenshot?: string;
  /** Individual element screenshots (default mode) */
  screenshots?: ElementScreenshot[];
  /** User's description of what should change */
  prompt?: string;
  /** URL of the annotated page */
  url?: string;
  /** Viewport dimensions at time of capture */
  viewport?: Viewport;
  /** True if user cancelled the annotation */
  cancelled?: boolean;
  /** True if annotation timed out */
  timeout?: boolean;
  /** Error or cancellation reason */
  reason?: string;
  editCapture?: EditCapture;
}

import { Type } from "typebox";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import * as net from "node:net";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import type { AnnotationResult, ElementSelection, EditCapture } from "./types.ts";
import { createRemoteAnnotationBridge, parseAnnotateCommandArgs, parseWslBridgeEnv, type RemoteAnnotationBridge } from "./remote.ts";

const IS_WINDOWS = process.platform === "win32";
const SOCKET_PATH = IS_WINDOWS ? "\\\\.\\pipe\\pi-annotate.sock" : "/tmp/pi-annotate.sock";
const TOKEN_PATH = IS_WINDOWS ? path.join(os.tmpdir(), "pi-annotate.token") : "/tmp/pi-annotate.token";
const MAX_SOCKET_BUFFER = 33 * 1024 * 1024; // 33MB: 1MB headroom over the native host's 32MB message limit for recovery envelopes
const MAX_SCREENSHOT_BYTES = 15 * 1024 * 1024; // 15MB

type AnnotationContext = {
  hasUI?: boolean;
  ui?: {
    notify?: (message: string, level: "info" | "error") => void;
    setStatus?: (source: string, message: string) => void;
  };
};

type RequestId = number & { readonly __brand: "RequestId" };

type HostConnectionOptions =
  | {
      transport: "socket";
      socketPath?: string;
      token?: string;
      tokenPath?: string;
      label?: string;
    }
  | {
      transport: "tcp";
      host: string;
      port: number;
      token: string;
      tokenPath: string;
      label: string;
    };

export default function (pi: ExtensionAPI) {
  let browserSocket: net.Socket | null = null;
  const pendingRequests = new Map<RequestId, (result: AnnotationResult) => void | Promise<void>>();
  let dataBuffer = ""; // Buffer for incomplete JSON messages
  let authToken: string | null = null;
  let connectedSocketPath: string | null = null;
  let currentCtx: AnnotationContext | null = null;
  let active = true;
  const remoteSessions = new Map<RequestId, RemoteAnnotationBridge>();
  let nextRequestId = Date.now();

  function setStatus(message: string) {
    if (active && currentCtx?.ui?.setStatus) {
      currentCtx.ui.setStatus("pi-annotate", message);
    }
  }

  function createRequestId(): RequestId {
    nextRequestId += 1;
    return nextRequestId as RequestId;
  }

  function parseRequestId(value: unknown): RequestId | null {
    if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) return null;
    return value as RequestId;
  }

  async function cancelPendingRequests(reason: string) {
    const result: AnnotationResult = {
      success: false,
      cancelled: true,
      reason,
      elements: [],
      url: "",
      viewport: { width: 0, height: 0 },
    };
    const requests = [...pendingRequests.values()];
    pendingRequests.clear();
    await Promise.allSettled(requests.map((resolvePending) => resolvePending(result)));
  }

  pi.on("session_shutdown", async () => {
    active = false;
    currentCtx = null;
    authToken = null;
    connectedSocketPath = null;
    dataBuffer = "";
    cleanupAllRemoteSessions();
    const socket = browserSocket;
    browserSocket = null;
    socket?.removeAllListeners();
    socket?.destroy();
    await cancelPendingRequests("session_shutdown");
  });

  // ─────────────────────────────────────────────────────────────────────
  // /annotate Command
  // ─────────────────────────────────────────────────────────────────────

  const annotateHandler = async (args: string, ctx: AnnotationContext) => {
    currentCtx = ctx;
    const parsed = parseAnnotateCommandArgs(args);
    const browserHost = parsed.mode === "browser-host" ? parsed.browserHost : null;
    let url = parsed.url;
    let remoteBridge: RemoteAnnotationBridge | null = null;

    try {
      if (browserHost) {
        setStatus(`Preparing remote annotation on ${browserHost}`);
        remoteBridge = await createRemoteAnnotationBridge(url === undefined ? { browserHost } : { browserHost, url });
        url = remoteBridge.url;
      }
      await connectToHost(remoteBridge ? {
        transport: "socket",
        socketPath: remoteBridge.socketPath,
        token: [REDACTED],
        label: `Browser Host ${browserHost}`,
      } : undefined);
      requestPendingCaptures();
    } catch (err) {
      remoteBridge?.cleanup();
      if (!active) return;
      const message = err instanceof Error ? err.message : String(err);
      const fallback = browserHost
        ? `Remote annotation failed for '${browserHost}'. ${message}`
        : `Browser extension not connected. ${message}. Click the Pi Annotate icon in the browser to wake the service worker, then retry.`;
      ctx.ui?.notify?.(fallback, "error");
      return;
    }

    if (!active) {
      remoteBridge?.cleanup();
      return;
    }

    const requestId = createRequestId();
    if (remoteBridge) remoteSessions.set(requestId, remoteBridge);
    sendToHost({
      type: "START_ANNOTATION",
      requestId,
      url,
    });

    if (browserHost) {
      ctx.ui?.notify?.(url ? `Opening annotation mode on ${browserHost}: ${url}` : `Annotation mode started on ${browserHost}'s current browser tab`, "info");
    } else {
      ctx.ui?.notify?.(url ? `Opening annotation mode on ${url}` : "Annotation mode started on current browser tab", "info");
    }
  };

  pi.registerCommand("annotate", {
    description: "Start visual annotation mode in the browser. Optionally provide a URL.",
    handler: annotateHandler,
  });

  // ─────────────────────────────────────────────────────────────────────
  // Socket Connection
  // ─────────────────────────────────────────────────────────────────────

  function defaultHostConnectionOptions(): HostConnectionOptions {
    const bridge = isWslSession() ? parseWslBridgeEnv() : null;
    if (!bridge) return { transport: "socket" };
    return {
      transport: "tcp",
      host: bridge.host,
      port: bridge.port,
      token: [REDACTED],
      tokenPath: "PI_ANNOTATE_WSL_TOKEN",
      label: `Windows Browser Host bridge at ${bridge.host}:${bridge.port}`,
    };
  }

  function connectionKey(options: HostConnectionOptions) {
    if (options.transport === "tcp") return `tcp://${options.host}:${options.port}`;
    return options.socketPath || SOCKET_PATH;
  }

  function isWslSession() {
    if (process.platform !== "linux") return false;
    if (process.env.WSL_DISTRO_NAME || process.env.WSL_INTEROP) return true;
    try {
      return /microsoft|wsl/i.test(fs.readFileSync("/proc/version", "utf8"));
    } catch {
      return false;
    }
  }

  function connectToHost(options: HostConnectionOptions = defaultHostConnectionOptions()): Promise<void> {
    return new Promise((resolve, reject) => {
      const key = connectionKey(options);
      const tokenPath = options.tokenPath || (options.transport === "socket" && options.token ? "remote Browser Host token" : TOKEN_PATH);
      const label = options.label || "native host";

      if (browserSocket && !browserSocket.destroyed) {
        if (connectedSocketPath === key) {
          resolve();
          return;
        }
        browserSocket.destroy();
        browserSocket = null;
        connectedSocketPath = null;
        dataBuffer = "";
      }

      try {
        authToken = [REDACTED] || fs.readFileSync(TOKEN_PATH, "utf8").trim();
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        reject(new Error(`Failed to read auth token at ${tokenPath}: ${message}`, { cause: err }));
        return;
      }

      const socket = options.transport === "tcp"
        ? net.createConnection(options.port, options.host)
        : net.createConnection(options.socketPath || SOCKET_PATH);
      browserSocket = socket;

      socket.on("connect", () => {
        connectedSocketPath = key;
        setStatus(`Connected to ${label}`);
        sendToHost({ type: "AUTH", token: authToken });
        resolve();
      });

      socket.on("data", (data) => {
        // Buffer incoming data and split by newlines
        dataBuffer += data.toString();
        if (dataBuffer.length > MAX_SOCKET_BUFFER) {
          setStatus("Error: Socket buffer overflow");
          socket.destroy();
          dataBuffer = "";
          return;
        }
        const lines = dataBuffer.split("\n");

        // Keep the last incomplete line in the buffer
        dataBuffer = lines.pop() || "";

        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const msg = JSON.parse(line);
            void handleMessage(msg).catch(() => {});
          } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            setStatus(`Error: Failed to parse message: ${message}`);
          }
        }
      });

      socket.on("error", (err) => {
        if (browserSocket === socket) setStatus(`Error: ${err.message}`);
        reject(err);
      });

      socket.on("close", () => {
        if (browserSocket !== socket) return;
        setStatus("Disconnected from native host");
        browserSocket = null;
        authToken = null;
        connectedSocketPath = null;
        dataBuffer = "";
        cleanupAllRemoteSessions();
        void cancelPendingRequests("connection_lost");
      });
    });
  }

  function sendToHost(msg: object) {
    if (browserSocket && !browserSocket.destroyed) {
      browserSocket.write(JSON.stringify(msg) + "\n");
    }
  }

  function requestPendingCaptures() {
    sendToHost({ type: "RECOVER_PENDING_ANNOTATIONS" });
  }

  function cleanupRemoteSession(requestId: RequestId | null) {
    if (requestId === null) return;
    const session = remoteSessions.get(requestId);
    if (!session) return;
    remoteSessions.delete(requestId);
    session.cleanup();
  }

  function cleanupAllRemoteSessions() {
    for (const session of remoteSessions.values()) {
      session.cleanup();
    }
    remoteSessions.clear();
  }

  function isRecord(value: unknown): value is Record<string, unknown> {
    return !!value && typeof value === "object" && !Array.isArray(value);
  }

  function isAnnotationResult(value: unknown): value is AnnotationResult {
    if (!isRecord(value)) return false;
    if (typeof value.success !== "boolean") return false;
    return true;
  }

  async function handleMessage(msg: unknown) {
    if (!active || !isRecord(msg) || typeof msg.type !== "string") return;

    setStatus(`Received: ${msg.type}`);

    const requestId = parseRequestId(msg.requestId);

    if (msg.type === "SESSION_REPLACED") {
      // Another terminal took over the annotation session
      setStatus("Session replaced by another terminal");
      const reason = typeof msg.reason === "string" ? msg.reason : "Session replaced by another terminal";

      // Resolve all pending requests with cancelled status
      await cancelPendingRequests(reason);
      cleanupAllRemoteSessions();

      // Connection will be destroyed by native host, so clean up
      browserSocket = null;
      connectedSocketPath = null;
      dataBuffer = "";
      return;
    }

    if (msg.type === "PENDING_ANNOTATIONS") {
      const captures = Array.isArray(msg.captures) ? msg.captures : [];
      const captureIds: string[] = [];
      let recovered = 0;
      for (const capture of captures) {
        if (!isRecord(capture) || typeof capture.id !== "string" || !isRecord(capture.message)) continue;
        const result = capture.message.result;
        if (!isAnnotationResult(result)) {
          captureIds.push(capture.id);
          continue;
        }
        const text = await formatResult(result);
        if (!active) return;
        pi.sendUserMessage(`## Recovered Pending Annotation\n\n${text}`);
        captureIds.push(capture.id);
        recovered += 1;
      }
      if (captureIds.length > 0) sendToHost({ type: "ACK_PENDING_ANNOTATIONS", captureIds });
      if (recovered > 0) setStatus(`Recovered ${recovered} pending annotation${recovered === 1 ? "" : "s"}`);
      return;
    }

    if (msg.type === "ANNOTATIONS_COMPLETE") {
      if (!isAnnotationResult(msg.result)) return;
      if (requestId !== null && pendingRequests.has(requestId)) {
        // Tool flow - resolve the promise
        const resolvePending = pendingRequests.get(requestId);
        if (!resolvePending) return;
        pendingRequests.delete(requestId);
        cleanupRemoteSession(requestId);
        await resolvePending(msg.result);
      } else {
        cleanupRemoteSession(requestId);
        // Command flow - inject as user message
        const result = msg.result;
        const text = await formatResult(result);
        if (!active) return;
        setStatus("Annotation complete");
        pi.sendUserMessage(text);
      }
    } else if (msg.type === "CANCEL") {
      cleanupRemoteSession(requestId);
      if (requestId !== null && pendingRequests.has(requestId)) {
        const resolvePending = pendingRequests.get(requestId);
        if (!resolvePending) return;
        pendingRequests.delete(requestId);
        await resolvePending({
          success: false,
          cancelled: true,
          reason: typeof msg.reason === "string" ? msg.reason : "user",
          elements: [],
          url: "",
          viewport: { width: 0, height: 0 },
        });
      }
      // For command flow, cancel is just ignored (UI already closed)
    }
  }

  // ─────────────────────────────────────────────────────────────────────
  // Format Result
  // ─────────────────────────────────────────────────────────────────────

  function formatEditCapture(capture: EditCapture): string {
    let output = "";

    if (capture.warnings?.length) {
      for (const w of capture.warnings) {
        output += `> **Note:** ${w}\n`;
      }
      output += "\n";
    }

    // Inline style changes
    if (capture.inlineStyles.length > 0) {
      output += `### Inline Style Changes\n\n`;
      for (const change of capture.inlineStyles) {
        output += `**\`${change.selector}\`**\n`;
        for (const c of change.changed) {
          output += `- \`${c.property}\`: \`${c.from}\` → \`${c.to}\`\n`;
        }
        for (const [prop, value] of Object.entries(change.added)) {
          output += `- \`${prop}\`: added \`${value}\`\n`;
        }
        for (const prop of change.removed) {
          output += `- \`${prop}\`: removed\n`;
        }
        output += "\n";
      }
    }

    // Stylesheet rule changes
    if (capture.rules.length > 0) {
      output += `### CSS Rule Changes\n\n`;
      for (const change of capture.rules) {
        output += `**\`${change.ruleSelector}\`** (${change.sheet})\n`;
        for (const c of change.changed) {
          output += `- \`${c.property}\`: \`${c.from}\` → \`${c.to}\`\n`;
        }
        for (const [prop, value] of Object.entries(change.added)) {
          output += `- \`${prop}\`: added \`${value}\`\n`;
        }
        for (const prop of change.removed) {
          output += `- \`${prop}\`: removed\n`;
        }
        output += "\n";
      }
    }

    // DOM changes
    if (capture.dom.length > 0) {
      output += `### DOM Changes\n\n`;
      for (const change of capture.dom) {
        output += `- **\`${change.selector}\`** — ${change.detail}\n`;
      }
      output += "\n";
    }

    return output;
  }

  async function formatResult(result: AnnotationResult): Promise<string> {
    if (!result.success) {
      if (result.cancelled) {
        if (result.reason?.includes("Another terminal")) {
          return `Annotation session ended: ${result.reason}`;
        }
        if (result.reason && result.reason !== "user") {
          return `Annotation cancelled: ${result.reason}`;
        }
        return "Annotation cancelled by user.";
      }
      return `Annotation failed: ${result.reason || "Unknown error"}`;
    }

    let output = `## Page Annotation: ${result.url || "Unknown"}\n`;
    if (result.viewport) {
      output += `**Viewport:** ${result.viewport.width}×${result.viewport.height}\n\n`;
    }

    // Show overall context if provided (uses existing 'prompt' field for backwards compat)
    if (result.prompt) {
      output += `**Context:** ${result.prompt}\n\n`;
    }

    // Check if any element has debug data (to show header)
    const hasDebugData = result.elements?.some(el => el.computedStyles || el.parentContext || el.cssVariables);
    if (hasDebugData) {
      output += `**Debug Mode:** Enabled\n\n`;
    }

    if (result.elements && result.elements.length > 0) {
      output += `### Selected Elements (${result.elements.length})\n\n`;
      result.elements.forEach((el: ElementSelection, i: number) => {
        output += `${i + 1}. **${el.tag}**\n`;
        output += `   - Selector: \`${el.selector}\`\n`;
        if (el.id) output += `   - ID: \`${el.id}\`\n`;
        if (el.classes?.length) output += `   - Classes: \`${el.classes.join(", ")}\`\n`;
        if (el.text) {
          output += `   - Text: "${el.text}"\n`;
        }

        // Box model (v0.3.0) - compact format
        if (el.boxModel) {
          const bm = el.boxModel;
          const padStr = `${bm.padding.top} ${bm.padding.right} ${bm.padding.bottom} ${bm.padding.left}`;
          const borderStr = bm.border.top || bm.border.right || bm.border.bottom || bm.border.left
            ? `${bm.border.top} ${bm.border.right} ${bm.border.bottom} ${bm.border.left}` : "0";
          const marginStr = `${bm.margin.top} ${bm.margin.right} ${bm.margin.bottom} ${bm.margin.left}`;
          output += `   - **Box Model:** ${el.rect.width}×${el.rect.height} (content: ${bm.content.width}×${bm.content.height}, padding: ${padStr}, border: ${borderStr}, margin: ${marginStr})\n`;
        } else {
          output += `   - Size: ${el.rect.width}×${el.rect.height}px\n`;
        }

        // Attributes (v0.3.0) - fix: was captured but never output
        if (el.attributes && Object.keys(el.attributes).length > 0) {
          const attrStr = Object.entries(el.attributes)
            .map(([k, v]) => `${k}="${v}"`)
            .join(", ");
          output += `   - **Attributes:** ${attrStr}\n`;
        }

        // Accessibility (v0.3.0) - compact format, omit undefined booleans
        if (el.accessibility) {
          const a11y = el.accessibility;
          const parts: string[] = [];
          if (a11y.role) parts.push(`role=${a11y.role}`);
          if (a11y.name) parts.push(`name="${a11y.name}"`);
          parts.push(`focusable=${a11y.focusable}`);
          parts.push(`disabled=${a11y.disabled}`);
          if (a11y.expanded !== undefined) parts.push(`expanded=${a11y.expanded}`);
          if (a11y.pressed !== undefined) parts.push(`pressed=${a11y.pressed}`);
          if (a11y.checked !== undefined) parts.push(`checked=${a11y.checked}`);
          if (a11y.selected !== undefined) parts.push(`selected=${a11y.selected}`);
          if (a11y.description) parts.push(`description="${a11y.description}"`);
          output += `   - **Accessibility:** ${parts.join(", ")}\n`;
        }

        // Key styles - compact format (suppressed when full computedStyles is present)
        const hasComputedStyles = el.computedStyles && Object.keys(el.computedStyles).length > 0;
        if (!hasComputedStyles && el.keyStyles && Object.keys(el.keyStyles).length > 0) {
          const styleStr = Object.entries(el.keyStyles).map(([k, v]) => `${k}: ${v}`).join(", ");
          output += `   - **Styles:** ${styleStr}\n`;
        }

        // Comment
        if (el.comment) {
          output += `   - **Comment:** ${el.comment}\n`;
        }

        // Debug mode data (v0.3.0) - verbose format
        if (el.computedStyles && Object.keys(el.computedStyles).length > 0) {
          output += `   - **Computed Styles:**\n`;
          for (const [key, value] of Object.entries(el.computedStyles)) {
            output += `     - ${key}: ${value}\n`;
          }
        }

        if (el.parentContext) {
          const pc = el.parentContext;
          const pcLabel = pc.id ? `${pc.tag}#${pc.id}` : `${pc.tag}${pc.classes[0] ? "." + pc.classes[0] : ""}`;
          const pcStyles = Object.entries(pc.styles).map(([k, v]) => `${k}: ${v}`).join(", ");
          output += `   - **Parent Context:** ${pcLabel} (${pcStyles})\n`;
        }

        if (el.cssVariables && Object.keys(el.cssVariables).length > 0) {
          output += `   - **CSS Variables:**\n`;
          for (const [name, value] of Object.entries(el.cssVariables)) {
            output += `     - ${name}: ${value}\n`;
          }
        }

        output += `\n`;
      });
    } else {
      output += "*No elements selected*\n\n";
    }

    // Handle screenshots
    const timestamp = Date.now();

    if (result.screenshot) {
      // Full page screenshot
      try {
        if (!result.screenshot.startsWith("data:image/")) throw new Error("Invalid screenshot data");
        const screenshotPath = path.join(os.tmpdir(), `pi-annotate-${timestamp}-full.png`);
        const base64Data = result.screenshot.replace(/^data:image\/\w+;base64,/, "");
        const buffer = Buffer.from(base64Data, "base64");
        if (buffer.length > MAX_SCREENSHOT_BYTES) throw new Error("Screenshot too large");
        await fs.promises.writeFile(screenshotPath, buffer);
        output += `**Screenshot (full page):** ${screenshotPath}\n`;
      } catch (err) {
        output += `*Screenshot capture failed: ${err}*\n`;
      }
    }

    if (result.screenshots && result.screenshots.length > 0) {
      // Individual element screenshots
      output += `### Screenshots\n\n`;
      for (let i = 0; i < result.screenshots.length; i++) {
        const shot = result.screenshots[i];
        try {
          if (!shot?.dataUrl?.startsWith("data:image/")) throw new Error("Invalid screenshot data");
          const safeIndex = Number.isFinite(shot.index) ? Math.max(1, Math.floor(shot.index)) : i + 1;
          const screenshotPath = path.join(os.tmpdir(), `pi-annotate-${timestamp}-el${safeIndex}.png`);
          const base64Data = shot.dataUrl.replace(/^data:image\/\w+;base64,/, "");
          const buffer = Buffer.from(base64Data, "base64");
          if (buffer.length > MAX_SCREENSHOT_BYTES) throw new Error("Screenshot too large");
          await fs.promises.writeFile(screenshotPath, buffer);
          output += `- Element ${safeIndex}: ${screenshotPath}\n`;
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          output += `- Element ${shot?.index ?? i + 1}: *capture failed (${message})*\n`;
        }
      }
      output += "\n";
    }

    if (result.editCapture && result.editCapture.changeCount > 0) {
      const ec = result.editCapture;
      output += `## Edit Capture (${ec.changeCount} changes, ${Math.round(ec.duration / 1000)}s)\n\n`;
      output += formatEditCapture(ec);

      // Before/after screenshots
      if (ec.beforeScreenshot || ec.afterScreenshot) {
        output += `### Before/After Screenshots\n\n`;
        if (ec.beforeScreenshot) {
          try {
            const p = path.join(os.tmpdir(), `pi-annotate-${timestamp}-before.png`);
            const buf = Buffer.from(ec.beforeScreenshot.replace(/^data:image\/\w+;base64,/, ""), "base64");
            if (buf.length > MAX_SCREENSHOT_BYTES) throw new Error("Screenshot too large");
            await fs.promises.writeFile(p, buf);
            output += `- Before: ${p}\n`;
          } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            output += `- Before: *capture failed (${message})*\n`;
          }
        }
        if (ec.afterScreenshot) {
          try {
            const p = path.join(os.tmpdir(), `pi-annotate-${timestamp}-after.png`);
            const buf = Buffer.from(ec.afterScreenshot.replace(/^data:image\/\w+;base64,/, ""), "base64");
            if (buf.length > MAX_SCREENSHOT_BYTES) throw new Error("Screenshot too large");
            await fs.promises.writeFile(p, buf);
            output += `- After: ${p}\n`;
          } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            output += `- After: *capture failed (${message})*\n`;
          }
        }
        output += "\n";
      }
    }

    return output;
  }

  // ─────────────────────────────────────────────────────────────────────
  // Tool Registration
  // ─────────────────────────────────────────────────────────────────────

  pi.registerTool({
    name: "annotate",
    label: "Annotate",
    description:
      "Open visual annotation mode in the browser so the user can click/select elements and add comments. " +
      "Only use when the user explicitly asks to annotate, visually point something out, or show you UI issues. " +
      "Returns structured annotations with CSS selectors and element info. " +
      "If no URL is provided, uses the current active browser tab.",
    promptSnippet:
      "Use only when the user explicitly asks for visual annotation or UI pointing. Call with {url?, browserHost?} and return selected element annotations.",
    parameters: Type.Object({
      url: Type.Optional(Type.String({
        description: "URL to annotate. If omitted, uses the current browser tab.",
      })),
      browserHost: Type.Optional(Type.String({
        description: "SSH host alias for the macOS/Linux Browser Host. If omitted, uses the same-machine browser.",
      })),
      timeout: Type.Optional(Type.Number({
        description: "Max seconds to wait for annotations. Default: 300 (5 min)",
      })),
    }),

    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      currentCtx = ctx;
      const { browserHost, timeout = 300 } = params as { url?: string; browserHost?: string; timeout?: number };
      let { url } = params as { url?: string };
      const requestId = createRequestId();
      let remoteBridge: RemoteAnnotationBridge | null = null;

      // Try to connect first
      try {
        if (browserHost) {
          remoteBridge = await createRemoteAnnotationBridge(url === undefined ? { browserHost } : { browserHost, url });
          url = remoteBridge.url;
        }
        await connectToHost(remoteBridge ? {
          transport: "socket",
          socketPath: remoteBridge.socketPath,
          token: [REDACTED],
          label: `Browser Host ${browserHost}`,
        } : undefined);
        requestPendingCaptures();
      } catch (err) {
        remoteBridge?.cleanup();
        const message = err instanceof Error ? err.message : String(err);
        return {
          content: [{ type: "text", text: browserHost ? `Remote annotation failed for '${browserHost}'. ${message}` : "Browser extension not connected. Click the Pi Annotate icon in the browser to wake the service worker, then retry." }],
          details: { error: message },
        };
      }

      if (remoteBridge) remoteSessions.set(requestId, remoteBridge);

      return new Promise((resolve) => {
        let timeoutId: NodeJS.Timeout | null = null;

        const cleanup = () => {
          if (timeoutId) clearTimeout(timeoutId);
          pendingRequests.delete(requestId);
          cleanupRemoteSession(requestId);
          signal?.removeEventListener("abort", onAbort);
        };

        const onAbort = () => {
          sendToHost({ type: "CANCEL", requestId, reason: "aborted" });
          cleanup();
          resolve({
            content: [{ type: "text", text: "Annotation was aborted." }],
            details: { aborted: true },
          });
        };

        // Handle abort signal
        if (signal?.aborted) {
          cleanup();
          return resolve({
            content: [{ type: "text", text: "Annotation was aborted." }],
            details: { aborted: true },
          });
        }
        signal?.addEventListener("abort", onAbort);

        // Set up response handler
        pendingRequests.set(requestId, async (result) => {
          cleanup();
          resolve({
            content: [{ type: "text", text: await formatResult(result) }],
            details: result,
          });
        });

        // Set timeout
        timeoutId = setTimeout(() => {
          sendToHost({ type: "CANCEL", requestId, reason: "timeout" });
          cleanup();
          resolve({
            content: [{ type: "text", text: `Annotation timed out after ${timeout}s` }],
            details: { timeout: true },
          });
        }, timeout * 1000);

        // Send start message
        sendToHost({
          type: "START_ANNOTATION",
          requestId,
          url,
        });

        if (ctx.hasUI) {
          ctx.ui?.notify?.(browserHost ? `Annotation mode started in ${browserHost}'s browser` : "Annotation mode started in the browser", "info");
        }
      });
    },
  });
}

